import 'dart:io';

import 'package:qelunai_lunar/qelunai_lunar.dart';
import 'package:test/test.dart';

/// Checks against NASA JPL's DE440s ephemeris, independent of any lunar
/// calendar implementation. `reference/*.csv` is generated by
/// `tool/jpl_reference.py` (local time UTC+7, 1900–2100).
///
/// The truncated Meeus series used in lib/src/core/ are accurate to well under a
/// minute for New Moons and about 0.01° (≈15 minutes) for the Sun, so a
/// disagreement is accepted only when the JPL instant is that close to
/// local midnight.
const Duration _newMoonTolerance = Duration(minutes: 2);
const Duration _solarTermTolerance = Duration(minutes: 10);

DateTime _parseLocal(String s) => DateTime.parse('${s}Z');

int _jdn(DateTime d) => jdnFromDate(day: d.day, month: d.month, year: d.year);

Duration _toNearestMidnight(DateTime t) {
  final midnight = DateTime.utc(t.year, t.month, t.day);
  final a = t.difference(midnight);
  final b = midnight.add(const Duration(days: 1)).difference(t);
  return a < b ? a : b;
}

void main() {
  test(
      'every New Moon falls on the JPL day, except within '
      '$_newMoonTolerance of midnight', () {
    final lines = File('reference/jpl_new_moons.csv').readAsLinesSync();
    final outside = <String>[];
    final tolerated = <String>[];
    for (final line in lines.skip(1)) {
      final t = _parseLocal(line);
      if (t.year < 1900 || t.year > 2100) continue;
      final lunar = solarToLunar(day: t.day, month: t.month, year: t.year);
      if (lunar.day == 1) continue;
      if (_toNearestMidnight(t) <= _newMoonTolerance) {
        tolerated.add(line);
      } else {
        outside.add('$line: got $lunar');
      }
    }
    expect(outside, isEmpty);
    // 1944-06-20 23:59:17 and 1967-07-07 23:59:59.
    expect(tolerated.length, lessThanOrEqualTo(2), reason: '$tolerated');
  });

  test(
      'solar-term index at every local midnight matches JPL, except '
      'within $_solarTermTolerance of a crossing', () {
    final rows = File('reference/jpl_solar_terms.csv')
        .readAsLinesSync()
        .skip(1)
        .map((l) => l.split(','))
        .map((c) => (index: int.parse(c[0]), start: _parseLocal(c[1])))
        .toList();
    final outside = <String>[];
    var tolerated = 0;
    var i = 0;
    for (var d = DateTime.utc(1900);
        d.year <= 2100;
        d = d.add(const Duration(days: 1))) {
      while (i + 1 < rows.length && !rows[i + 1].start.isAfter(d)) {
        i++;
      }
      final expected = rows[i].index;
      final got = solarTermIndex(_jdn(d), vietnamTimeZone);
      if (got == expected) continue;
      final nearest = [rows[i].start, rows[i + 1].start]
          .map((s) => s.difference(d).abs())
          .reduce((a, b) => a < b ? a : b);
      if (nearest <= _solarTermTolerance) {
        tolerated++;
      } else {
        outside.add('${d.toIso8601String().substring(0, 10)}: '
            'got $got, JPL $expected');
      }
    }
    expect(outside, isEmpty);
    expect(tolerated, lessThanOrEqualTo(11));
  });
}
